# rewardkit calls criteria concurrently; locks prevent duplicate singleton creation under the race.
_SHIPPED_DIR: list[Path] = []
_TOOL_DIR: list[Path] = []
_SHIPPED_LOCK = threading.Lock()
_TOOL_LOCK = threading.Lock()
