def shipped_dir() -> Path:
    with _SHIPPED_LOCK:
        if not _SHIPPED_DIR:
            root = Path(tempfile.mkdtemp(prefix="evidence-"))
            root.chmod(0o755)
            for rel, blob in _BLOBS.items():
                tgt = root / rel
                tgt.parent.mkdir(parents=True, exist_ok=True)
                tgt.write_bytes(zlib.decompress(base64.b64decode(blob)))
                tgt.chmod(0o644)
            _SHIPPED_DIR.append(root)
        return _SHIPPED_DIR[0]


def doc(name: str) -> Any:
    return json.loads((shipped_dir() / name).read_text(encoding="utf-8"))


def raw(name: str) -> str:
    return (shipped_dir() / name).read_text(encoding="utf-8")


def defs() -> list[dict]:
    specs = []
    for idx, slug in enumerate(SLUG_LIST):
        wire = WIRE[idx % len(WIRE)]
        hi = {42: 9007199254740952, 48: 9007199254740993}.get(idx, 500 + 17 * idx)
        specs.append({"name": f"c{idx + 1:02d}_{slug}", "ext": EXT_OF[wire], "fmt": wire,
                      "op": OP_LIST[idx % len(OP_LIST)], "lo": 1 + (idx % 5), "hi": hi})
    return specs


def as_int(token: Any) -> int | None:
    if not isinstance(token, str):
        return None
    try:
        parsed = int(token)
    except (TypeError, ValueError):
        return None
    return parsed if str(parsed) == token else None


def keep(zone: str, value: str, flag: str, lo: int, hi: int) -> int | None:
    if zone not in ZONE_LIST or flag != "active":
        return None
    parsed = as_int(value)
    if parsed is None or not (lo <= parsed <= hi):
        return None
    return parsed


def _jf(x: Any) -> str:
    if isinstance(x, bool):
        return "true" if x else "false"
    if x is None:
        return ""
    if isinstance(x, int):
        return str(x)
    if isinstance(x, float):
        return repr(x)
    return str(x)


def triples(fmt: str, body: str) -> list[tuple[str, str, str]]:
    plain = {"csv": ",", "tsv": "\t", "psv": "|", "scsv": ";", "colon": ":",
             "caret": "^", "at": "@", "bang": "!", "tilde": "~"}
    collected: list[tuple[str, str, str]] = []
    if fmt in plain:
        token = plain[fmt]
        for line in body.splitlines():
            trimmed = line.strip()
            if not trimmed or trimmed.startswith("#"):
                continue
            # fields are the exact bytes between separators; surrounding spaces are rejected later
            cut = line.split(token)
            if len(cut) != 3:
                continue
            triple = (cut[0], cut[1], cut[2])
            if triple != ("zone", "value", "flag"):
                collected.append(triple)
        return collected
    if fmt == "dcolon":
        for line in body.splitlines():
            trimmed = line.strip()
            if trimmed and not trimmed.startswith("#"):
                cut = line.split("::")
                if len(cut) == 3:
                    collected.append((cut[0], cut[1], cut[2]))
        return collected
    if fmt == "ssv":
        for line in body.splitlines():
            trimmed = line.strip()
            if not trimmed or trimmed.startswith("#"):
                continue
            cut = trimmed.split()
            if len(cut) == 3 and cut[0] != "zone":
                collected.append((cut[0], cut[1], cut[2]))
        return collected
    if fmt in ("jsonarr", "jsonl"):
        records: list[Any] = []
        if fmt == "jsonarr":
            try:
                blob = json.loads(body)
                records = blob if isinstance(blob, list) else []
            except ValueError:
                records = []
        else:
            for line in body.splitlines():
                trimmed = line.strip()
                if trimmed and not trimmed.startswith("//"):
                    try:
                        records.append(json.loads(trimmed))
                    except ValueError:
                        pass
        for item in records:
            if isinstance(item, dict):
                collected.append((_jf(item.get("zone")), _jf(item.get("value")), _jf(item.get("flag"))))
        return collected
    if fmt == "xmlflat":
        try:
            tree = ET.fromstring(body)
        except ET.ParseError:
            return collected
        return [(e.get("zone", ""), e.get("value", ""), e.get("flag", "")) for e in tree.findall("row")]
    if fmt == "xmlnest":
        try:
            tree = ET.fromstring(body)
        except ET.ParseError:
            return collected
        for e in tree.findall("row"):
            collected.append((e.findtext("zone", "").strip(), e.findtext("value", "").strip(), e.findtext("flag", "").strip()))
        return collected
    if fmt == "ini":
        parser = configparser.ConfigParser()
        try:
            parser.read_string(body)
        except configparser.Error:
            return collected
        for section in parser.sections():
            block = parser[section]
            collected.append((block.get("zone", ""), block.get("value", ""), block.get("flag", "")))
        return collected
    if fmt == "fixed":
        for line in body.splitlines():
            if not line.strip() or line.lstrip().startswith("#") or line[:10].strip() == "zone":
                continue
            collected.append((line[0:10].strip(), line[10:30].strip(), line[30:].strip()))
        return collected
    if fmt == "mdtable":
        for line in body.splitlines():
            trimmed = line.strip()
            if not trimmed.startswith("|"):
                continue
            cells = [c.strip() for c in trimmed.strip("|").split("|")]
            if len(cells) == 3 and cells[0] != "zone" and not set(cells[0]) <= set("-: "):
                collected.append((cells[0], cells[1], cells[2]))
        return collected
    if fmt == "kvline":
        for line in body.splitlines():
            trimmed = line.strip()
            if not trimmed or trimmed.startswith("#"):
                continue
            pairs = dict(seg.split("=", 1) for seg in trimmed.split() if "=" in seg)
            if {"zone", "value", "flag"} <= set(pairs):
                collected.append((pairs["zone"], pairs["value"], pairs["flag"]))
        return collected
    if fmt == "props":
        buckets: dict[str, dict[str, str]] = {}
        seen: list[str] = []
        for line in body.splitlines():
            trimmed = line.strip()
            if not trimmed or trimmed.startswith("#") or "=" not in trimmed:
                continue
            left, _, right = trimmed.partition("=")
            if "." not in left:
                continue
            head, _, tail = left.partition(".")
            if head not in buckets:
                buckets[head] = {}
                seen.append(head)
            buckets[head][tail] = right
        for head in seen:
            group = buckets[head]
            collected.append((group.get("zone", ""), group.get("value", ""), group.get("flag", "")))
        return collected
    return collected


def reduce_corpus(op: str, rows: list[tuple[str, str, str]], lo: int, hi: int) -> int:
    counted = [n for (z, v, f) in rows if (n := keep(z, v, f, lo, hi)) is not None]
    if op == "count":
        return len(counted)
    if not counted:
        return 0
    if op == "max":
        return max(counted)
    if op == "min":
        return min(counted)
    if op == "sum":
        return sum(counted)
    if op == "last":
        return counted[-1]
    return counted[0]


def wanted_aggregates() -> dict[str, int]:
    base_shift = rekey_shift()
    result = {}
    for spec in defs():
        rows = triples(spec["fmt"], raw(f"{spec['name']}.{spec['ext']}"))
        hi_eff = hi_fixpoint(spec, rows, base_shift)
        result[spec["name"]] = reduce_corpus(spec["op"], rows, spec["lo"], hi_eff)
    return result


def wanted_zone_totals() -> dict[str, int]:
    base_shift = rekey_shift()
    tally = {z: 0 for z in ZONE_LIST}
    for spec in defs():
        rows = triples(spec["fmt"], raw(f"{spec['name']}.{spec['ext']}"))
        hi_eff = hi_fixpoint(spec, rows, base_shift)
        for (z, v, f) in rows:
            if keep(z, v, f, spec["lo"], hi_eff) is not None:
                tally[z] += 1
    return tally


def wanted_index() -> dict:
    agg = wanted_aggregates()
    base_shift = rekey_shift()
    entries = []
    for spec in defs():
        rows = triples(spec["fmt"], raw(f"{spec['name']}.{spec['ext']}"))
        hi_eff = hi_fixpoint(spec, rows, base_shift)
        live = _elig_count(spec, rows, hi_eff)
        entries.append({"name": spec["name"], "format": spec["fmt"], "op": spec["op"],
                        "lo": spec["lo"], "hi": spec["hi"], "eligible_rows": live, "value": agg[spec["name"]]})
    return {"corpora": entries, "count": len(entries)}


def wanted_posture() -> dict:
    agg = wanted_aggregates()
    # ties on value broken by the EARLIER name (lexicographically first), per contract
    best = min(agg.items(), key=lambda kv: (-kv[1], kv[0]))
    return {"aggregate_total": sum(agg.values()), "corpus_count": len(agg),
            "max_corpus": best[0], "max_value": best[1],
            "nonzero_corpora": sum(1 for v in agg.values() if v > 0)}


def journal_sorted() -> list[dict]:
    rows = [json.loads(line) for line in raw("change_journal.jsonl").splitlines() if line.strip()]
    return sorted(rows, key=lambda o: o["seq"])


def op_ok(op: dict, rules: dict) -> bool:
    if op["env"] not in rules["journal_envs"]:
        return False
    kind = op.get("op", "set")
    if kind == "unset":
        return op["key"] in SPINE or op["key"] == "mode"
    if kind != "set":
        return False
    if op["key"] == "mode":
        return op["value"] in rules["allowed_modes"]
    if op["key"] in SPINE:
        lo, hi = rules["bounds"][op["key"]]
        return type(op["value"]) is int and lo <= op["value"] <= hi
    return False


def wanted_rejected() -> list[int]:
    rules = doc("validation_rules.json")
    return [o["seq"] for o in journal_sorted() if not op_ok(o, rules)]


def replay(seed_doc: dict, env: str) -> dict:
    rules = doc("validation_rules.json")
    base = doc("defaults.json")
    spine_defaults = base["base_config"]
    for op in journal_sorted():
        if op["env"] == env and op_ok(op, rules):
            if op.get("op", "set") == "unset":
                seed_doc[op["key"]] = spine_defaults[op["key"]] if op["key"] in SPINE else base["mode"]
            else:
                seed_doc[op["key"]] = op["value"]
    return seed_doc


def rekey_shift() -> int:
    return (wanted_config()["rekey_interval_s"] % 97) + (len(wanted_rejected()) % 31)


def _elig_count(spec, rows, hi_eff):
    return sum(1 for (z, v, f) in rows if keep(z, v, f, spec["lo"], hi_eff) is not None)


def hi_fixpoint(spec, rows, base_shift):
    e_cur = 0
    hi_eff = spec["hi"] + base_shift
    for _ in range(32):
        hi_eff = spec["hi"] + base_shift + (e_cur % 7)
        new_e = _elig_count(spec, rows, hi_eff)
        if new_e == e_cur:
            return hi_eff
        e_cur = new_e
    return hi_eff


def wanted_config() -> dict:
    base = doc("defaults.json")
    schema = doc("config_schema.json")
    seed_doc = {"checksum": base["checksum"], "container": schema["container"], "mode": base["mode"],
                "producer": schema["producer"], "profile": schema["profile"], **base["base_config"]}
    return replay(seed_doc, "base")


def wanted_profile(zone: str) -> dict:
    merged = dict(wanted_config())
    ov = doc("env_overrides.json")[zone]
    merged["retry_budget"] += int(ov["retry_budget_delta"])
    merged["handshake_timeout_ms"] += int(ov["handshake_timeout_ms_delta"])
    merged["rekey_interval_s"] += int(ov["rekey_interval_s_delta"])
    merged["mode"] = ov["mode"]
    merged["profile"] = f"{merged['profile']}-{zone}"
    merged["trailer"] = f"{merged['trailer']}:{zone}"
    return replay(merged, zone)


def load(name: str) -> Any:
    return json.loads((OUT / name).read_text(encoding="utf-8"))


def staged_config() -> Path:
    stage = Path(tempfile.mkdtemp(prefix="sealb-cfg-"))
    stage.chmod(0o755)
    dest = stage / "config.json"
    dest.write_bytes((OUT / "config.json").read_bytes())
    dest.chmod(0o644)
    return dest


def extracted_tool() -> Path:
    with _TOOL_LOCK:
        if _TOOL_DIR:
            return _TOOL_DIR[0]
        root = Path(tempfile.mkdtemp(prefix="sealb-tool-"))
        root.chmod(0o755)
        with zipfile.ZipFile(OUT / "tool.zip") as zf:
            for info in zf.infolist():
                rel = Path(info.filename)
                assert not rel.is_absolute() and ".." not in rel.parts
                dest = root / rel
                dest.parent.mkdir(parents=True, exist_ok=True)
                if dest.parent != root:
                    dest.parent.chmod(0o755)
                dest.write_bytes(zf.read(info))
                dest.chmod(0o644)
        _TOOL_DIR.append(root)
        return root


def source_text() -> str:
    try:
        root = extracted_tool()
    except Exception:
        return ""
    chunks = []
    for name in ("cli.py", "schema.json"):
        p = root / name
        if p.exists():
            chunks.append(p.read_text(encoding="utf-8", errors="replace"))
    return "\n".join(chunks)


def run_tool(*args: str) -> subprocess.CompletedProcess[str]:
    root = extracted_tool()
    cmd = [sys.executable, "-I", str(root / "cli.py"), *args]
    drop_priv = _UNTRUSTED and os.name == "posix" and os.geteuid() == 0 and os.path.exists(_UNTRUSTED[0])
    if drop_priv:
        cmd = [*_UNTRUSTED, *cmd]
    env = {"PATH": "/usr/local/bin:/usr/bin:/bin", "PYTHONHASHSEED": "0",
           "PYTHONDONTWRITEBYTECODE": "1", "LANG": "C.UTF-8", "LC_ALL": "C.UTF-8"}
    with subprocess.Popen(cmd, cwd="/tmp", text=True, stdout=subprocess.PIPE,
                          stderr=subprocess.PIPE, start_new_session=True, env=env) as proc:
        try:
            stdout, stderr = proc.communicate(timeout=120)
            returncode = proc.returncode
        except subprocess.TimeoutExpired:
            stdout, stderr, returncode = "", "timeout", -1
        finally:
            try:
                os.killpg(proc.pid, signal.SIGKILL)
            except (OSError, ProcessLookupError):
                pass
    return subprocess.CompletedProcess(cmd, returncode, stdout, stderr)


def _holds(fn) -> bool:
    try:
        fn()
    except Exception:
        return False
    return True


def _artifacts_exist():
    for name in ARTIFACTS:
        p = OUT / name
        assert p.is_file() and p.stat().st_size > 0, name
    assert (OUT / "config.json").stat().st_size > 100


def _config_keys():
    data = load("config.json")
    assert isinstance(data, dict)
    assert set(doc("config_schema.json")["required_keys"]) <= set(data)
    assert all(type(data[k]) is int for k in SPINE)


def _config_policy():
    assert load("config.json") == wanted_config()


def _profiles_match():
    for z in ZONE_LIST:
        data = load(f"profile_{z}.json")
        assert data == wanted_profile(z)
        assert all(not isinstance(v, (dict, list)) for v in data.values())


def _aggregates_json():
    assert load("aggregates.json") == wanted_aggregates()


def _expected_view(kind: str) -> str:
    items = sorted(load("aggregates.json").items())
    assert len(items) == 50
    assert all(isinstance(v, int) and not isinstance(v, bool) for _, v in items)
    assert [k for k, _ in items] == sorted(spec["name"] for spec in defs())
    if kind == "csv":
        return "corpus,value\n" + "".join(f"{k},{v}\n" for k, v in items)
    if kind == "tsv":
        return "corpus\tvalue\n" + "".join(f"{k}\t{v}\n" for k, v in items)
    if kind == "ini":
        return "[aggregates]\n" + "".join(f"{k} = {v}\n" for k, v in items)
    if kind == "env":
        return "".join(f"{k.upper()}={v}\n" for k, v in items)
    if kind == "md":
        return "| corpus | value |\n| --- | --- |\n" + "".join(f"| {k} | {v} |\n" for k, v in items)
    if kind == "txt":
        return "".join(f"{k} {v}\n" for k, v in items)
    root = ET.Element("aggregates")
    for k, v in items:
        ET.SubElement(root, "corpus", {"name": k, "value": str(v)})
    return ET.tostring(root, encoding="unicode") + "\n"


