def _report_transcript():
    report = load("report.json")
    commands = report["commands"]
    assert report["ok"] is True and report["tool"] == "sealb-ctl"
    assert isinstance(commands, list) and len(commands) >= 6
    seen = "\n".join(" ".join(item.get("argv", [])) for item in commands)
    for token in ("init", "set", "validate", "compile"):
        assert token in seen
    assert all(item.get("returncode") == 0 for item in commands)
    staged = str(staged_config())
    staged_schema = str(extracted_tool() / "schema.json")
    saw_validate = False
    for item in commands:
        argv = item["argv"]
        if "validate" not in argv:
            continue
        saw_validate = True
        tail = argv[argv.index("validate"):]
        cli_args = []
        i = 0
        while i < len(tail):
            tok = tail[i]
            if tok == "--config" and i + 1 < len(tail):
                cli_args.extend([tok, staged])
                i += 2
            elif tok == "--schema" and i + 1 < len(tail):
                cli_args.extend([tok, staged_schema])
                i += 2
            else:
                cli_args.append(tok)
                i += 1
        observed = run_tool(*cli_args)
        assert observed.returncode == item["returncode"]
        assert observed.stdout.strip() == item.get("stdout", "").strip()
    assert saw_validate


