def _cli_repaired():
    root = extracted_tool()
    schema_path = str(root / "schema.json")
    scratch = Path(tempfile.mkdtemp(prefix="sealb-scratch-"))
    scratch.chmod(0o755)
    tmp_config = scratch / "config.json"
    tmp_config.write_text("{}", encoding="utf-8")
    tmp_config.chmod(0o666)
    init = run_tool("init", "--schema", schema_path, "--out", str(tmp_config))
    assert init.returncode == 0, init.stderr or init.stdout
    seeded = json.loads(tmp_config.read_text(encoding="utf-8"))
    assert isinstance(seeded, dict) and seeded
    assert all(not isinstance(v, (dict, list)) for v in seeded.values())
    tmp_config.chmod(0o666)
    coerced = run_tool("set", "--config", str(tmp_config), "--key", "max_sessions", "--value", "321")
    assert coerced.returncode == 0, coerced.stderr or coerced.stdout
    updated = json.loads(tmp_config.read_text(encoding="utf-8"))
    assert updated["max_sessions"] == 321
    planned = run_tool("plan", "--data", str(shipped_dir()), "--env", "base")
    assert planned.returncode == 0, planned.stderr or planned.stdout
    doc = json.loads(planned.stdout)
    assert set(SPINE).issubset(doc)
    assert all(isinstance(doc[k], int) for k in SPINE)
    assert doc == wanted_config()


def _json_canonical():
    for name in JSON_ARTIFACTS:
        blob = (OUT / name).read_bytes()
        obj = json.loads(blob.decode("utf-8"))
        assert isinstance(obj, dict) and obj
        want = json.dumps(obj, sort_keys=True, indent=2, separators=(",", ": "), ensure_ascii=False) + "\n"
        assert blob == want.encode("utf-8"), name


