def _tool_zip_deterministic():
    with zipfile.ZipFile(OUT / "tool.zip") as zf:
        infos = zf.infolist()
        assert infos
        names = [i.filename for i in infos]
        assert names == sorted(names)
        for info in infos:
            assert info.compress_type == zipfile.ZIP_STORED
            assert info.date_time == (1980, 1, 1, 0, 0, 0)
            assert info.external_attr == (0o100644 << 16)
        with zipfile.ZipFile(shipped_dir() / "tool.zip") as shipped:
            shipped_cli = shipped.read("cli.py")
        assert zf.read("cli.py") != shipped_cli


def _compile_reproducible():
    agent_config = (OUT / "config.json").read_bytes()
    a = Path(tempfile.mkdtemp(prefix="sealb-c1-"))
    b = Path(tempfile.mkdtemp(prefix="sealb-c2-"))
    for d in (a, b):
        d.chmod(0o777)
        (d / "config.json").write_bytes(agent_config)
        (d / "config.json").chmod(0o644)
        r = run_tool("compile", "--data", str(shipped_dir()), "--out", str(d))
        assert r.returncode == 0, r.stderr or r.stdout
    names = sorted(p.name for p in a.iterdir() if p.is_file() and p.name != "config.json")
    assert "aggregates.json" in names
    assert names == sorted(p.name for p in b.iterdir() if p.is_file() and p.name != "config.json")
    for n in names:
        assert (a / n).read_bytes() == (b / n).read_bytes(), n


